import { useId, type KeyboardEvent, type ReactNode } from 'react'
import { SYMPTOMS, symptomLabel, type SymptomArea } from '../data/indicators'
import type { Symptom } from '../engine/types'
import { FIGURES, HEAD_PATH, type BodyType, type FigureShapes } from './bodyShapes'

/**
 * Front and back body map in the muscle-map style, male or female figure.
 * Original drawing: every shape is generated by scripts/body_shapes.py.
 * Display mode colours the areas where symptoms were reported.
 * Input mode (onSelect): every area is a button that jumps to its symptoms in the check-in.
 */

type Tone = 'idle' | 'hit' | 'severe'
const SEVERE = 7

function hits(symptoms: Symptom[]) {
  const out: Partial<Record<SymptomArea, { max: number; labels: string[] }>> = {}
  for (const s of symptoms) {
    const area = SYMPTOMS.find((d) => d.id === s.id)?.area
    if (!area) continue
    const h = (out[area] ??= { max: 0, labels: [] })
    h.max = Math.max(h.max, s.intensity)
    h.labels.push(`${symptomLabel(s.id)} ${s.intensity}/10`)
  }
  return out
}

// Palette (literal classes so Tailwind generates them)
const IDLE = { limb: 'fill-[#a9bfcf]', core: 'fill-[#8cc9c2]', kidney: 'fill-[#76b8b0]', clear: 'fill-transparent' }
const HIT: Record<Exclude<Tone, 'idle'>, string> = { hit: 'fill-amber-400', severe: 'fill-red-500' }
const OUTLINE: Record<Tone, string> = { idle: 'stroke-slate-700', hit: 'stroke-amber-500', severe: 'stroke-red-500' }
const PILL: Record<Tone, string> = { idle: 'border-slate-300 bg-white text-slate-600', hit: 'border-amber-400 bg-amber-100 text-amber-900', severe: 'border-red-400 bg-red-100 text-red-900' }
const BACK_X = 130

export function BodyMap({ symptoms, body = 'male', selected, onSelect, dim = false, className = '' }: {
  symptoms: Symptom[]
  body?: BodyType
  selected?: SymptomArea | null
  onSelect?: (area: SymptomArea) => void
  dim?: boolean
  className?: string
}) {
  const uid = useId().replace(/[^a-zA-Z0-9]/g, '')
  const h = hits(symptoms)
  const tone = (a: SymptomArea): Tone => (!h[a] ? 'idle' : h[a].max >= SEVERE ? 'severe' : 'hit')
  const label = (a: SymptomArea) => `${a}: ${h[a] ? h[a].labels.join(', ') : 'nothing reported'}`
  const sel = (a: SymptomArea) => selected === a

  /** Fill and outline of one shape of an area. */
  const paint = (a: SymptomArea, idle: keyof typeof IDLE, separate = false) => {
    const t = tone(a)
    const clear = idle === 'clear'
    const fill = t !== 'idle' ? HIT[t] : sel(a) ? (clear ? 'fill-sky-300/80' : 'fill-sky-300') : IDLE[idle]
    const hover = onSelect && t === 'idle' && !sel(a) ? (clear ? 'group-hover:fill-sky-200/70' : 'group-hover:fill-sky-200 group-focus-visible:fill-sky-200') : ''
    const stroke = sel(a) ? 'stroke-navy' : onSelect ? `${separate ? 'stroke-white' : 'stroke-transparent'} group-focus-visible:stroke-sky-600` : separate ? 'stroke-white' : 'stroke-transparent'
    // An unselected shape keeps a wide transparent stroke: it makes the white gaps between muscles clickable too.
    return { className: `${fill} ${hover} ${stroke} transition-colors`, strokeWidth: sel(a) ? 1.4 : separate ? 1.3 : 2.8 }
  }

  /** One area. Areas drawn in both views get a single keyboard stop. */
  const area = (a: SymptomArea, children: ReactNode, dup = false) =>
    onSelect ? (
      <g
        key={`${a}${dup ? '-dup' : ''}`}
        role="button"
        tabIndex={dup ? -1 : 0}
        aria-hidden={dup || undefined}
        aria-label={dup ? undefined : label(a)}
        aria-pressed={dup ? undefined : sel(a)}
        className="group cursor-pointer outline-none"
        onClick={() => onSelect(a)}
        onKeyDown={(e: KeyboardEvent<SVGGElement>) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault()
            onSelect(a)
          }
        }}
      >
        <title>{label(a)}</title>
        {children}
      </g>
    ) : (
      <g key={`${a}${dup ? '-dup' : ''}`}>
        <title>{label(a)}</title>
        {children}
      </g>
    )

  const skin = tone('Skin')
  const joints = tone('Muscles & joints')
  const line = 'pointer-events-none fill-none stroke-slate-700'

  const figure = (F: FigureShapes, back: boolean) => {
    const areas = Object.entries(F.areas) as [SymptomArea, readonly string[]][]
    const overlays = Object.entries(F.overlay) as [SymptomArea, readonly string[]][]
    const ears = (
      <>
        <ellipse cx={45.6} cy={26.5} rx={2.6} ry={5} />
        <ellipse cx={74.4} cy={26.5} rx={2.6} ry={5} />
      </>
    )
    return (
      <>
        {/* skin: a thick stroke behind the fill hides the seams between parts */}
        <g className={`fill-white ${OUTLINE[skin]}`} strokeWidth={skin === 'idle' ? 2.2 : 4.5} strokeLinejoin="round">
          {F.skin.map((d) => <path key={d} d={d} />)}
          {ears}
        </g>
        <g className="fill-white">
          {F.skin.map((d) => <path key={d} d={d} />)}
          {ears}
        </g>

        {area('Head', <path d={HEAD_PATH} {...paint('Head', 'clear')} />, back)}
        {areas.map(([a, shapes]) => {
          const kidney = back && a === 'Urinary'
          const idle = a === 'Muscles & joints' ? 'limb' : kidney ? 'kidney' : 'core'
          return area(a, shapes.map((d) => <path key={d} d={d} {...paint(a, idle, kidney)} />), back && a !== 'Back')
        })}
        <g className="pointer-events-none fill-[#1e3a5f]">{F.clothes.map((d) => <path key={d} d={d} />)}</g>
        {overlays.map(([a, shapes]) => area(a, shapes.map((d) => <path key={d} d={d} {...paint(a, 'clear')} />)))}
        <g className="pointer-events-none fill-[#24344d]">{F.hair.map((d) => <path key={d} d={d} />)}</g>

        {F.face && (
          <>
            {area('Vision', <rect clipPath={`url(#${uid}-head)`} x={48} y={20.6} width={24} height={5.6} rx={2.8} {...paint('Vision', 'clear')} />)}
            {area('Mouth', <ellipse cx={60} cy={34.5} rx={5} ry={2.6} {...paint('Mouth', 'clear')} />)}
            <g className={line} strokeLinecap="round">
              <path d="M51.6 19.8 Q54.6 18.4 57.6 19.6" strokeWidth={1.1} />
              <path d="M68.4 19.8 Q65.4 18.4 62.4 19.6" strokeWidth={1.1} />
              <path d="M60 24.5 L59.2 29.6 Q60 30.3 61 29.9" strokeWidth={0.8} />
              <path d="M57 34.4 Q60 35.3 63 34.4" strokeWidth={1} />
            </g>
            <g className="pointer-events-none fill-slate-700"><ellipse cx={54.6} cy={23.4} rx={1.5} ry={1} /><ellipse cx={65.4} cy={23.4} rx={1.5} ry={1} /></g>
          </>
        )}
        {joints !== 'idle' && (
          <g className={`pointer-events-none stroke-white ${joints === 'severe' ? 'fill-red-700' : 'fill-amber-600'}`} strokeWidth={1}>
            {F.joints.map(([x, y]) => <circle key={`${x}-${y}`} cx={x} cy={y} r={3.2} />)}
          </g>
        )}
      </>
    )
  }

  const reported = Object.keys(h) as SymptomArea[]
  const summary = reported.length ? `Body map, front and back. Symptoms reported in: ${reported.join(', ')}.` : 'Body map, front and back. No symptoms reported.'
  const fig = FIGURES[body]

  return (
    <div className={className}>
      <svg viewBox="0 -8 250 324" className={`block h-auto w-full ${dim ? 'opacity-40' : ''}`} {...(onSelect ? { role: 'group', 'aria-label': 'Body map, front and back: choose an area' } : { role: 'img', 'aria-label': summary })}>
        <defs>
          <clipPath id={`${uid}-head`}><path d={HEAD_PATH} /></clipPath>
        </defs>
        <g>{figure(fig.front, false)}</g>
        <g transform={`translate(${BACK_X} 0)`}>{figure(fig.back, true)}</g>
        <text x={60} y={312} textAnchor="middle" fontSize={9.5} className="fill-slate-500">Front</text>
        <text x={BACK_X + 60} y={312} textAnchor="middle" fontSize={9.5} className="fill-slate-500">Back</text>
      </svg>

      <div className="mt-1.5 flex flex-col items-center gap-1.5">
        {onSelect ? (
          <button type="button" onClick={() => onSelect('Skin')} aria-pressed={sel('Skin')} aria-label={label('Skin')} className={`rounded-full border px-3 py-0.5 text-xs font-semibold ${PILL[skin]} ${sel('Skin') ? 'ring-2 ring-navy' : ''}`}>
            Skin (whole body)
          </button>
        ) : (
          skin !== 'idle' && <span className={`rounded-full border px-2.5 py-0.5 text-xs font-semibold ${PILL[skin]}`} title={label('Skin')}>Skin</span>
        )}
        <div className="flex flex-wrap justify-center gap-x-2.5 gap-y-0.5 text-[10px] text-slate-500">
          <span className="inline-flex items-center gap-1"><span className="size-2 rounded-full bg-amber-400" aria-hidden />reported</span>
          <span className="inline-flex items-center gap-1"><span className="size-2 rounded-full bg-red-500" aria-hidden />intensity ≥ {SEVERE}</span>
        </div>
      </div>
    </div>
  )
}
